define('DOING_CRON',true);require __DIR__.'/m0/bootstrap.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/builder.php';require __DIR__.'/study-engine/cross-sectional/support.php';require __DIR__.'/study-engine/persistence/support.php';require __DIR__.'/study-engine/longitudinal/support.php';
use EIPSI\StudyEngine\Builder as B;use EIPSI\StudyEngine\Longitudinal as L;
$tests=0;$failures=0;$subscriber=wp_insert_user(array('user_login'=>'email-library-'.bin2hex(random_bytes(6)),'user_pass'=>wp_generate_password(),'role'=>'subscriber'));$prior=get_option(B\EmailLibrary::OPTION,false);$GLOBALS['pf_now']='2026-10-13T11:00:00Z';
function em_case($name,$fn){global $tests,$failures;$tests++;try{$fn();echo 'PASS '.$name."\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}
function em_api($op,$args=array()){return B\Admin::handle(array_merge(array('operation'=>$op),$args),wp_create_nonce('eipsi_study_builder'));}
function em_entry(){return array('name'=>'Template de prueba','purpose'=>'ASSESSMENT_AVAILABLE','subject'=>'[study_name]: [assessment_name]','html'=>'<p><strong>Hola</strong> [study_name] <a href="[direct_link]">Abrir</a></p>','from_name'=>'Equipo de prueba','from_email'=>'sender@example.test');}
try{pe_assert(EIPSI_Schema_Installer::repair_local_schema()['success'],'Schema repair');delete_option(B\EmailLibrary::OPTION);wp_set_current_user(1);
em_case('Email library requires admin capability and valid CSRF for read write preview delete',function(){foreach(array(0,$GLOBALS['subscriber']) as $user){wp_set_current_user($user);foreach(array('email_library','email_library_save','email_template_preview','email_library_delete') as $op)pe_reject(function()use($op){em_api($op);},'BUILDER_FORBIDDEN');}wp_set_current_user(1);pe_reject(function(){B\Admin::handle(array('operation'=>'email_library'),'invalid');},'BUILDER_CSRF');});
em_case('Global create update and stale revision protect library atomically',function(){ $a=em_api('email_library');pe_assert(count($a['defaults'])===3&&$a['templates']===array(),'Defaults modified stored library');foreach($a['defaults'] as $purpose=>$default){pe_assert($default['subject']!==''&&$default['html']!==''&&$default['from_name']!=='','Empty default field');$preview=B\EmailLibrary::preview(array_merge(array('purpose'=>$purpose),$default));pe_assert(substr_count($preview['html'],'Administrar comunicaciones')===0&&substr_count($preview['html'],'Abandonar estudio')===1,'Duplicated default footer');pe_assert(strpos($default['html'],'href="[direct_link]"')!==false&&strpos($default['html'],'href="[withdrawal_link]"')!==false,'Default editor body incomplete');foreach(array('access','withdrawal') as $link)pe_assert(substr_count($preview['html'],'href="https://example.invalid/'.$link.'"')===1,'Missing or duplicated '.$link);} $a=em_api('email_library_save',array('revision'=>$a['revision'],'entry'=>em_entry()));pe_assert($a['revision']===1&&count($a['templates'])===1,'Create failed');$t=$a['templates'][0];$GLOBALS['em_template']=$t;$e=em_entry();$e['id']=$t['id'];$e['name']='Editado';$b=em_api('email_library_save',array('revision'=>1,'entry'=>$e));pe_assert($b['revision']===2&&$b['templates'][0]['revision']===2,'Update failed');pe_reject(function()use($e){em_api('email_library_save',array('revision'=>1,'entry'=>$e));},'EMAIL_LIBRARY_REVISION');pe_equal($b,em_api('email_library'),'Stale write changed library');});
em_case('Malformed sender variables and executable markup cannot enter templates',function(){ $before=em_api('email_library');foreach(array(array('from_email'=>"evil@example.test\r\nBcc: victim@example.test"),array('subject'=>'[unknown_variable]'),array('html'=>'{{unknown}}')) as $patch){$e=array_merge(em_entry(),$patch);try{em_api('email_library_save',array('revision'=>$before['revision'],'entry'=>$e));throw new RuntimeException('Malformed template accepted');}catch(DomainException $error){pe_assert(strpos($error->getMessage(),'INVALID')!==false||strpos($error->getMessage(),'UNKNOWN')!==false,'Wrong validation error');}}pe_equal($before,em_api('email_library'));$t=L\InitialScreen::template(array('subject'=>'','html'=>'<p><strong>Bien</strong><script>alert(1)</script><img src="javascript:x" onerror="x"></p>'));pe_assert(strpos($t['html'],'<script')===false&&strpos($t['html'],'onerror')===false,'Unsafe HTML');});
em_case('Whitelisted bracket and historical variables preview safely without email or library writes',function(){ $before=em_api('email_library');$mail=count($GLOBALS['m0_mail']??array());$e=em_entry();unset($e['name']);$e['html'].='<p>{{study_name}} [withdrawal_link]</p><p><a href="[direct_link]">Abrir mi evaluación</a></p>';$r=em_api('email_template_preview',array('entry'=>$e));pe_assert(strpos($r['subject'],'Estudio de ejemplo')!==false&&strpos($r['html'],'https://example.invalid/access')!==false&&strpos($r['html'],'[study_name]')===false&&strpos($r['html'],'Abandonar estudio')===false&&strpos($r['html'],'Administrar comunicaciones')===false,'Preview added text outside template');pe_assert($r['from_email']===''&&count($GLOBALS['m0_mail']??array())===$mail,'Preview sent email');pe_equal($before,em_api('email_library'));});
em_case('Published study snapshots survive library edits and deletion',function(){ $saved=$GLOBALS['pf_now'];try{ $t=$GLOBALS['em_template'];$c=L\InitialScreen::defaults();$c['templates']['ASSESSMENT_AVAILABLE']=array_intersect_key($t,array_flip(array('subject','html','from_name','from_email')))+array('source_id'=>$t['id'],'source_revision'=>$t['revision'],'source_name'=>$t['name']);$p=pf_publish('04',array('initial_screen'=>$c));$v=(new EIPSI\StudyEngine\Persistence\StudyVersionRepository(pf_db()))->find($p['version']);$before=$v['protocol_json'];$library=em_api('email_library');em_api('email_library_delete',array('id'=>$t['id'],'revision'=>$library['revision']));$after=(new EIPSI\StudyEngine\Persistence\StudyVersionRepository(pf_db()))->find($p['version']);pe_assert($after['protocol_json']===$before&&$after['protocol_hash']===$v['protocol_hash'],'Library changed immutable snapshot');$f=pf_enroll($p);$intents=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE');usort($intents,static function($a,$b){return strcmp($a['trigger_at'],$b['trigger_at']);});$i=$intents[0];$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($i['trigger_at'].' UTC'));pe_assert(pf_delivery($i)['success'],'Snapshot delivery failed');$mail=end($GLOBALS['m0_mail']);pe_assert(strpos($mail['subject'],'[study_name]')===false&&strpos($mail['message'],'<strong>Hola</strong>')!==false,'Snapshot not used');}finally{$GLOBALS['pf_now']=$saved;}});
em_case('Delivery sender uses validated per-message headers without global SMTP mutation',function(){ $smtp=get_option('eipsi_smtp_config',false);$captured=null;$filter=static function($result,$args)use(&$captured){$captured=$args;return true;};add_filter('pre_wp_mail',$filter,999,2);try{pe_assert(EIPSI_Notification_Email_Delivery_Service::send_study_engine('recipient@example.test','Prueba',array('html'=>'<p>Prueba</p>','from_name'=>'Equipo','from_email'=>'sender@example.test'),'NI_SENDER'),'Delivery failed');pe_assert(strpos(implode(' ',(array)$captured['headers']),'sender@example.test')!==false,'Sender header missing');pe_assert(apply_filters('wp_mail_from_name','Original')==='Original','Sender filter leaked');pe_equal($smtp,get_option('eipsi_smtp_config',false));}finally{remove_filter('pre_wp_mail',$filter,999);}});
em_case('Global email page renders scoped editor assets and no SMTP credentials',function(){ $r=m0_http('/wp-admin/admin.php?page=eipsi-email-templates',null,true);$html=wp_remote_retrieve_body($r);pe_assert(wp_remote_retrieve_response_code($r)===200&&strpos($html,'id="eipsi-email-library"')!==false&&strpos($html,'assessment-editor.js')!==false,'Library screen unavailable');pe_assert(strpos($html,'name="smtp_password"')===false,'Credentials included');});
em_case('Email library deletion cannot remove another template or accept stale state',function(){ $d=em_api('email_library');$d=em_api('email_library_save',array('revision'=>$d['revision'],'entry'=>em_entry()));$id=$d['templates'][0]['id'];pe_reject(function()use($id,$d){em_api('email_library_delete',array('id'=>$id,'revision'=>$d['revision']-1));},'EMAIL_LIBRARY_REVISION');$after=em_api('email_library_delete',array('id'=>$id,'revision'=>$d['revision']));pe_assert(count($after['templates'])===0,'Delete failed');});
