 foreach(array('VERIFY_PARTICIPANT','ASSESSMENT_AVAILABLE','ASSESSMENT_REMINDER') as $purpose){$entry=array('purpose'=>$purpose,'subject'=>'Asunto propio [study_name]','html'=>'<p><strong>Contenido propio</strong> [assessment_name]</p>');$render=B\EmailLibrary::preview($entry);pe_assert($render['subject']==='Asunto propio Estudio de ejemplo','Subject replaced');pe_assert($render['html']==='<p><strong>Contenido propio</strong> Evaluación de ejemplo</p>','Extra email content');}
