 $entry=em_entry();$entry['subject']='';$entry['html']='';$lib=em_api('email_library');$saved=em_api('email_library_save',array('revision'=>$lib['revision'],'entry'=>$entry));$t=end($saved['templates']);pe_assert($t['subject']===''&&$t['html']==='','Blank fields changed');$preview=B\EmailLibrary::preview(array('purpose'=>$entry['purpose'],'subject'=>'','html'=>''));pe_assert($preview['subject']===''&&$preview['html']==='','Preview restored defaults');em_api('email_library_delete',array('id'=>$t['id'],'revision'=>$saved['revision']));
