em_case('Unverified participant receives the exact configured body through the real worker',function(){
 $saved=$GLOBALS['pf_now'];try{$c=L\InitialScreen::defaults();$c['authentication']['verification']='IMMEDIATE';$c['templates']['ASSESSMENT_AVAILABLE']=array('subject'=>'Asunto exacto','html'=>'<p>Únicamente mi texto.</p>','source_id'=>'ET_EXACT','source_revision'=>1);$p=pf_publish('03',array('initial_screen'=>$c));$f=pf_enroll($p,'exact-template@example.test');$intents=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT');pe_assert(count($intents)>0,'Validation intent missing');$intent=$intents[0];pe_assert($intent['block_execution_id']!==null,'Immediate opportunity fixture required');pe_assert(pf_delivery($intent)['success'],'Delivery failed');$mail=end($GLOBALS['m0_mail']);pe_assert($mail['subject']==='Asunto exacto'&&$mail['message']==='<p>Únicamente mi texto.</p>','Worker appended text or used another template');$dummy=B\Experience::run($p['definition'],array('created_at'=>$GLOBALS['pf_now'],'timezone'=>'UTC'),array(array('kind'=>'ENTER','data'=>array('email'=>'exact-template@example.test'))),array());pe_assert($dummy['emails'][0]['content']['subject']===$mail['subject']&&$dummy['emails'][0]['content']['html']===$mail['message'],'Simulation differs from actual delivery');}finally{$GLOBALS['pf_now']=$saved;}
});
