 foreach(array('[communications_link]','{{communications_link}}') as $token){$t=L\InitialScreen::template(array('subject'=>'Mi asunto','html'=>'<p>Hola</p><a href="[direct_link]">Entrar</a> · <a href="'.$token.'">Administrar comunicaciones</a> · <a href="[withdrawal_link]">Salir</a>'));pe_assert(strpos($t['html'],'communications')===false&&strpos($t['html'],'Administrar')===false&&strpos($t['html'],'[direct_link]')!==false&&strpos($t['html'],'[withdrawal_link]')!==false,'Retired link retained or other links removed');}
