em_case('Migration removes preference column and obsolete credentials while preserving participants and published protocols',function(){
 global $wpdb;$p=pf_publish();$f=pf_enroll($p);$db=pf_db();$before=(new EIPSI\StudyEngine\Persistence\StudyVersionRepository($db))->find($p['version']);$participant=pf_participant($f);$cap=pf_mint($f);$db->query($db->prepare('UPDATE '.$db->table('access_capabilities')." SET purpose='COMMUNICATION_OPTIONS' WHERE token_hash=%s",hash('sha256',$cap)));pe_reject(function()use($p,$cap){pf_runtime()->redeem($p['public'],$cap);},'ACCESS_REQUIRED');$db->query($db->prepare('UPDATE '.$db->table('participant_sessions')." SET kind='COMMUNICATION_OPTIONS' WHERE recovery_hash=%s",hash('sha256',$f['token'])));pe_assert((new L\Identity($db,pf_clock()))->recover($p['public'],$f['token'])===null,'Retired session accepted');$table=$db->table('participants');$wpdb->query("ALTER TABLE $table ADD COLUMN communications_enabled tinyint(1) NOT NULL DEFAULT 0");$library=array('revision'=>5,'templates'=>array(array('subject'=>'Original','html'=>'<p>Contenido</p><a href="[communications_link]">Administrar comunicaciones</a>')));update_option(B\EmailLibrary::OPTION,$library,false);update_option(EIPSI_Migration_Runner::VERSION_OPTION,16,false);$result=(new EIPSI_Migration_Runner())->run();pe_assert($result['success'],'Migration failed');pe_assert(!$wpdb->get_var($wpdb->prepare('SHOW COLUMNS FROM '.$table.' LIKE %s','communications_enabled')),'Preference column remains');pe_assert((int)$wpdb->get_var("SELECT COUNT(*) FROM ".$db->table('access_capabilities')." WHERE purpose='COMMUNICATION_OPTIONS'")===0,'Retired credentials remain');pe_assert((int)$wpdb->get_var("SELECT COUNT(*) FROM ".$db->table('participant_sessions')." WHERE kind='COMMUNICATION_OPTIONS'")===0,'Retired sessions remain');$after=(new EIPSI\StudyEngine\Persistence\StudyVersionRepository($db))->find($p['version']);pe_equal($before,$after,'Published protocol changed');pe_equal($participant,pf_participant($f),'Participant changed');$saved=get_option(B\EmailLibrary::OPTION);pe_assert($saved['revision']===6&&$saved['templates'][0]['html']==='<p>Contenido</p>','Library cleanup changed other content');pe_assert((new EIPSI_Migration_Runner())->run()['success'],'Repeated migration failed');pe_equal($saved,get_option(B\EmailLibrary::OPTION),'Repeated migration modified library');delete_option(B\EmailLibrary::OPTION);
});
}finally{wp_set_current_user(1);require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($subscriber);if($prior===false)delete_option(B\EmailLibrary::OPTION);else update_option(B\EmailLibrary::OPTION,$prior,false);}
